      {"q": "Where is the largest collection of Benin Bronzes currently held?", "o": ["National Museum Lagos", "Benin Royal Museum", "British Museum, London", "Louvre, Paris"], "a": 2, "e": "The British Museum holds the largest collection — approximately 900 objects acquired after the 1897 punitive expedition.", "h": "Largest Benin Bronze collection = British Museum, London.", "yr": "SS1"},
      {"q": "Benin ivory masks and carved tusks served which purpose?", "o": ["Everyday household objects", "Royal ceremonial objects — worn by the Oba or placed on royal altars", "Trade items for European markets", "Children's educational objects"], "a": 1, "e": "Benin ivory carvings were royal ceremonial objects — large carved tusks placed on royal ancestor altars and ivory masks worn by the Oba during ceremonies.", "h": "Benin ivory = royal ceremonial objects (altars + Oba's ceremonies).", "yr": "SS1"}
